T = {}
for line in _T.strip().splitlines():
    k, v = line.split(' = ', 1)
    cols = v.split('|')
    assert len(cols) == 11, (k, len(cols))
    T[k] = cols


def minutes(n):
    """'5 min' in every language: (English, [translations])."""
    return f'{n} min', [f'{n}{"" if l in ("zh", "ja", "ko") else " "}{T["min"][i]}' for i, l in enumerate(LANGS)]


for n in (1, 2, 3, 5, 10, 15, 20, 25, 30, 45, 50, 60, 90):
    k, v = minutes(n)
    T[k] = v
for n in range(1, 5):
    T[f'City {n}'] = [f'{c} {n}' for c in T['City']]
